import React from "react";
import { SEO } from "../utils/SEO";

const UserGuide = () => {
  const can = window.location.href;

  return (
    <>
      <SEO
        title="4ceps | How Our E-Commerce Works - User Guide"
        description="Comprehensive guide on how 4ceps E-Commerce works, including Seller Registration, Verification, Order Management, Prescription Handling, and Delivery."
        url={can}
      />
      <div className="container py-5" style={{ maxWidth: "1000px" }}>
        {/* Header Section */}
        <div className="text-center mb-5">
          <h2
            className="fw-800 text-heading font-outfit mb-2"
            style={{ fontSize: "28px" }}
          >
            HOW OUR E COMMERCE WORKS
          </h2>
          <p className="text-muted fw-600 mb-2" style={{ fontSize: "14px" }}>
            Website: <strong>4ceps.com</strong> ("4CEPS", "Website", "Platform", "We", "Us", or "Our") is operated by{" "}
            <strong>RKTLC Innovations Pvt. Ltd.</strong>
          </p>
          <div className="d-flex justify-content-center gap-2 flex-wrap">
            <span
              className="badge px-3 py-1.5 fw-700 rounded-pill font-13"
              style={{ backgroundColor: "#F3E8FF", color: "#A847F0" }}
            >
              Effective Date: 18 August 2026
            </span>
            <span
              className="badge px-3 py-1.5 fw-700 rounded-pill font-13"
              style={{ backgroundColor: "#E0F2FE", color: "#0284C7" }}
            >
              Last Updated: 18 August 2026
            </span>
          </div>
        </div>

        {/* Content Card */}
        <div
          className="card border-0 shadow-sm rounded-4 p-4 p-md-5"
          style={{ backgroundColor: "#ffffff", lineHeight: "1.7", color: "#334155" }}
        >
          {/* 1. SELLER REGISTRATION */}
          <div className="mb-4 pb-3 border-bottom">
            <h4 className="fw-800 mb-3" style={{ color: "#A847F0", fontSize: "18px" }}>
              1. SELLER REGISTRATION
            </h4>
            <p className="font-14 text-dark mb-2">
              Healthcare providers, pharmacies, laboratories, diagnostic centres, hospitals, clinics and other eligible sellers may register on 4CEPS.
            </p>
            <p className="font-14 text-dark mb-2 fw-600">
              Sellers are required to provide accurate business and regulatory information, including:
            </p>
            <ul className="list-unstyled d-flex flex-column gap-1 ps-3 mb-0">
              <li className="font-14 text-dark">• Business/centre name</li>
              <li className="font-14 text-dark">• Contact details</li>
              <li className="font-14 text-dark">• Address</li>
              <li className="font-14 text-dark">• Applicable licences and registrations</li>
              <li className="font-14 text-dark">• GST details, where applicable</li>
              <li className="font-14 text-dark">• Products or services offered</li>
              <li className="font-14 text-dark">• Other documents requested by 4CEPS</li>
            </ul>
          </div>

          {/* 2. SELLER VERIFICATION */}
          <div className="mb-4 pb-3 border-bottom">
            <h4 className="fw-800 mb-3" style={{ color: "#A847F0", fontSize: "18px" }}>
              2. SELLER VERIFICATION
            </h4>
            <ul className="list-unstyled d-flex flex-column gap-2 ps-3 mb-0">
              <li className="font-14 text-dark">
                • 4CEPS may review the information and documents submitted by the seller before approving the account.
              </li>
              <li className="font-14 text-dark">
                • 4CEPS may request additional documents or clarification where required by mail.
              </li>
              <li className="font-14 text-dark">
                • Approval does not constitute a guarantee or certification of the seller's products or services.
              </li>
            </ul>
          </div>

          {/* 3. SELLER PROFILE */}
          <div className="mb-4 pb-3 border-bottom">
            <h4 className="fw-800 mb-3" style={{ color: "#A847F0", fontSize: "18px" }}>
              3. SELLER PROFILE
            </h4>
            <p className="font-14 text-dark mb-2">
              Approved sellers may create and maintain a profile containing relevant information such as:
            </p>
            <ul className="list-unstyled d-flex flex-column gap-1 ps-3 mb-2">
              <li className="font-14 text-dark">• Business information</li>
              <li className="font-14 text-dark">• Location</li>
              <li className="font-14 text-dark">• Contact details</li>
              <li className="font-14 text-dark">• Social media links</li>
            </ul>
            <p className="font-14 text-dark mb-0">
              Sellers are responsible for ensuring that their profile information remains accurate and up to date.
            </p>
          </div>

          {/* 4. ORDER MANAGEMENT */}
          <div className="mb-4 pb-3 border-bottom">
            <h4 className="fw-800 mb-3" style={{ color: "#A847F0", fontSize: "18px" }}>
              4. ORDER MANAGEMENT
            </h4>
            <p className="font-14 text-dark mb-3">
              <strong>4ceps.com</strong> is an online marketplace for delivery of health products like medicines, medical devices, surgical instruments &amp; equipment, health supplements, cosmetics &amp; veterinary products.
            </p>

            {/* BUYER FINAL PRICE */}
            <div className="mb-3 p-3 rounded-3" style={{ backgroundColor: "#F8FAFC", border: "1px solid #E2E8F0" }}>
              <h5 className="fw-700 text-heading font-15 mb-2" style={{ color: "#475569" }}>
                BUYER FINAL PRICE
              </h5>
              <p className="font-14 text-dark mb-0">
                The platform has inbuilt data of health products like medicines, medical devices, surgical instruments &amp; equipment, health supplements, cosmetics &amp; veterinary products. Buyer can search any health products. The products searched may be added into the cart along with quantity required. After all products are added into the cart, he will upload copy of prescription against each item where prescription is mandatory. Buyer can edit any of the details before check out. If patient do not upload prescription, the system will allow to check out only if prescription is not mandatory. If prescription is mandatory, system will not allow to check out until prescription is uploaded. The MRP including all applicable taxes will be displayed. The buyer can proceed to get final price from the 4ceps sellers if all data is correct.
              </p>
            </div>

            {/* FINAL PRICE */}
            <div className="mb-3 p-3 rounded-3" style={{ backgroundColor: "#F8FAFC", border: "1px solid #E2E8F0" }}>
              <h5 className="fw-700 text-heading font-15 mb-2" style={{ color: "#475569" }}>
                FINAL PRICE
              </h5>
              <p className="font-14 text-dark mb-0">
                As soon as the buyer proceeds with <strong>GET FINAL PRICE</strong>, the request for price will be shared with all sellers of SUCH health products. The buyer will be notified to wait for <strong>20 minutes</strong> to check availability, price &amp; delivery by sellers. In this 20 minutes, the sellers of REQUESTED PRODUCTS will check whether prescription is mandatory, the correctness of prescription, availability (if not available he will share the quotation of similar alternative products), quantity (whether full requested quantity is available or partial quantity) whether minimum period of 3 months validity is available, determine his price &amp; discount and 5 percent platform fees, whether he delivers freely to buyer’s location if yes in what duration. If no delivery is provided by seller, then he can give option of getting delivered by the third party logistics provider after payment is made to him &amp; collect products by the delivery agent of logistics provider by paying delivery charges. Store pick up option is also available. This entire process has to be completed in 20 minutes &amp; shared with buyer. The buyer will be shown final discounted price with applicable taxes.
              </p>
            </div>

            {/* ORDER PLACEMENT */}
            <div className="mb-3 p-3 rounded-3" style={{ backgroundColor: "#F8FAFC", border: "1px solid #E2E8F0" }}>
              <h5 className="fw-700 text-heading font-15 mb-2" style={{ color: "#475569" }}>
                ORDER PLACEMENT
              </h5>
              <p className="font-14 text-dark mb-2">
                After 20 minutes, the buyer will get display of all quotations received within 20 minutes in order of ascending order of price &amp; delivery duration. He will also get notified whether same drug or quantity as requested or similar alternative brand &amp; partial quantity available or only few products are available. He will place order based on seller, price &amp; delivery duration. He should place order within <strong>10 minutes</strong>.
              </p>
              <p className="font-14 text-dark fw-600 mb-1">He can choose mode of delivery:</p>
              <ul className="list-unstyled d-flex flex-column gap-1 ps-3 mb-3">
                <li className="font-14 text-dark">• Store pick up</li>
                <li className="font-14 text-dark">• Free delivery by seller if available</li>
                <li className="font-14 text-dark">
                  • Paid delivery by third party logistics provider. If delivered by the third party logistics provider, payment is to be made to seller through UPI or any other mutually agreed mode. Seller may share QR code with buyer through WhatsApp. The buyer has to collect products by the delivery agent of logistics provider by paying delivery charges.
                </li>
              </ul>
              <div className="p-2.5 rounded-2 font-13 fw-700 border" style={{ backgroundColor: "#EFF6FF", color: "#1D4ED8", borderColor: "#BFDBFE" }}>
                ⚠️ THE SELLER HAS TO DELIVER ONLY THROUGH COLD CHAIN LOGISTICS IF PRODUCTS REQUIRE TEMPERATURE REGULATION.
              </div>
              <p className="font-14 text-dark mt-3 mb-0">
                Those sellers who miss the 20 minutes deadline are given an additional <strong>10 minutes</strong> time to send quotations. But these quotations appear on the buyer's dashboard after cumulative 30 minutes and stay for <strong>5 minutes</strong>. If buyer has not confirmed order in 10 minutes window due to any reason, he/she can confirm orders in this 5 minute window where all quotations appear.
              </p>
            </div>

            {/* REORDER & REPEAT ORDER */}
            <div className="p-3 rounded-3" style={{ backgroundColor: "#F8FAFC", border: "1px solid #E2E8F0" }}>
              <h5 className="fw-700 text-heading font-15 mb-2" style={{ color: "#475569" }}>
                REORDER &amp; REPEAT ORDER
              </h5>
              <p className="font-14 text-dark mb-2">
                After 35 minutes, live orders disappear from both seller &amp; buyer dashboard &amp; <strong>REFLECT IN PAST ORDERS</strong>.
              </p>
              <p className="font-14 text-dark mb-0">
                The buyer can reorder any time after expiry of live order with or without editing. The seller can share same saved quotation against said request with or without editing. The buyer can also repeat order after products are delivered.
              </p>
            </div>
          </div>

          {/* 5. PRESCRIPTION PRODUCTS */}
          <div className="mb-4 pb-3 border-bottom">
            <h4 className="fw-800 mb-3" style={{ color: "#A847F0", fontSize: "18px" }}>
              5. PRESCRIPTION PRODUCTS
            </h4>
            <ul className="list-unstyled d-flex flex-column gap-2 ps-3 mb-0">
              <li className="font-14 text-dark">
                • Where applicable, prescription medicines or regulated products must be supplied only after verification of a valid prescription and in accordance with applicable laws.
              </li>
              <li className="font-14 text-dark">
                • Sellers are responsible for complying with all applicable requirements relating to prescription verification, dispensing and record keeping.
              </li>
            </ul>
          </div>

          {/* 6. PRICING AND AVAILABILITY */}
          <div className="mb-4 pb-3 border-bottom">
            <h4 className="fw-800 mb-3" style={{ color: "#A847F0", fontSize: "18px" }}>
              6. PRICING AND AVAILABILITY
            </h4>
            <p className="font-14 text-dark mb-0">
              Sellers are responsible for quoted correct pricing and availability information.
            </p>
          </div>

          {/* 7. PAYMENT AND PLATFORM FEES */}
          <div className="mb-4 pb-3 border-bottom">
            <h4 className="fw-800 mb-3" style={{ color: "#A847F0", fontSize: "18px" }}>
              7. PAYMENT AND PLATFORM FEES
            </h4>
            <ul className="list-unstyled d-flex flex-column gap-2 ps-3 mb-0">
              <li className="font-14 text-dark">
                • Applicable platform fees, commissions, transaction charges or other commercial terms will be governed by the agreement between 4CEPS and the seller.
              </li>
              <li className="font-14 text-dark">
                • Where applicable, eligible seller settlements will be processed after successful completion of the relevant transaction, subject to applicable deductions, refunds, cancellations and other agreed terms.
              </li>
            </ul>
          </div>

          {/* 8. ORDER CANCELLATION */}
          <div className="mb-4 pb-3 border-bottom">
            <h4 className="fw-800 mb-3" style={{ color: "#A847F0", fontSize: "18px" }}>
              8. ORDER CANCELLATION
            </h4>
            <ul className="list-unstyled d-flex flex-column gap-2 ps-3 mb-0">
              <li className="font-14 text-dark">
                • Sellers should not cancel confirmed orders without a valid reason.
              </li>
              <li className="font-14 text-dark">
                • Where cancellation is necessary due to stock unavailability, operational issues or other legitimate reasons, the seller should promptly update the order status and inform the customer/platform where applicable.
              </li>
              <li className="font-14 text-dark">
                • Repeated or unjustified cancellations may result in account review or suspension.
              </li>
            </ul>
          </div>

          {/* 9. DELIVERY AND FULFILMENT */}
          <div className="mb-4 pb-3 border-bottom">
            <h4 className="fw-800 mb-3" style={{ color: "#A847F0", fontSize: "18px" }}>
              9. DELIVERY AND FULFILMENT
            </h4>
            <ul className="list-unstyled d-flex flex-column gap-2 ps-3 mb-0">
              <li className="font-14 text-dark">
                • Sellers are responsible for ensuring that products are properly packed, stored and handed over for delivery in accordance with applicable requirements.
              </li>
              <li className="font-14 text-dark">
                • Products requiring special storage or handling must be maintained under appropriate conditions.
              </li>
              <li className="font-14 text-dark">
                • Delivery timelines may vary depending on location, availability and logistics arrangements.
              </li>
            </ul>
          </div>

          {/* 10. RETURNS AND REFUNDS */}
          <div className="mb-4 pb-3 border-bottom">
            <h4 className="fw-800 mb-3" style={{ color: "#A847F0", fontSize: "18px" }}>
              10. RETURNS AND REFUNDS
            </h4>
            <p className="font-14 text-dark mb-0">
              Products that are damaged, incorrect, expired or otherwise eligible for return must be handled according to applicable law and this is between seller &amp; buyer &amp; platform has no role &amp; only facilitates for smooth process.
            </p>
          </div>

          {/* 11. SELLER RESPONSIBILITIES */}
          <div className="mb-4 pb-3 border-bottom">
            <h4 className="fw-800 mb-3" style={{ color: "#A847F0", fontSize: "18px" }}>
              11. SELLER RESPONSIBILITIES
            </h4>
            <p className="font-14 text-dark mb-2 fw-600">Sellers are responsible for:</p>
            <ul className="list-unstyled d-flex flex-column gap-1 ps-3 mb-0">
              <li className="font-14 text-dark">• Maintaining valid licences and registrations;</li>
              <li className="font-14 text-dark">• Complying with applicable laws and regulations;</li>
              <li className="font-14 text-dark">• Supplying genuine and legally authorised products;</li>
              <li className="font-14 text-dark">• Maintaining product quality and safety;</li>
              <li className="font-14 text-dark">• Maintaining appropriate storage conditions;</li>
              <li className="font-14 text-dark">• Providing accurate information;</li>
              <li className="font-14 text-dark">• Properly fulfilling confirmed orders;</li>
              <li className="font-14 text-dark">• Maintaining required records; and</li>
              <li className="font-14 text-dark">• Cooperating with reasonable verification or compliance requests from 4CEPS.</li>
            </ul>
          </div>

          {/* 12. PROHIBITED ACTIVITIES */}
          <div className="mb-4 pb-3 border-bottom">
            <h4 className="fw-800 mb-3" style={{ color: "#A847F0", fontSize: "18px" }}>
              12. PROHIBITED ACTIVITIES
            </h4>
            <p className="font-14 text-dark mb-2 fw-600">Sellers must not:</p>
            <ul className="list-unstyled d-flex flex-column gap-1 ps-3 mb-0">
              <li className="font-14 text-dark">• Sell counterfeit products;</li>
              <li className="font-14 text-dark">• Sell expired products;</li>
              <li className="font-14 text-dark">• Provide false or misleading information;</li>
              <li className="font-14 text-dark">• Manipulate prices or orders;</li>
              <li className="font-14 text-dark">• Use another seller's identity or documents;</li>
              <li className="font-14 text-dark">• Conduct fraudulent transactions;</li>
              <li className="font-14 text-dark">• Upload unauthorised content;</li>
              <li className="font-14 text-dark">• Circumvent applicable prescription requirements; or</li>
              <li className="font-14 text-dark">• Use the platform for any unlawful purpose.</li>
            </ul>
          </div>

          {/* 13. ACCOUNT SUSPENSION */}
          <div className="mb-4 pb-3 border-bottom">
            <h4 className="fw-800 mb-3" style={{ color: "#A847F0", fontSize: "18px" }}>
              13. ACCOUNT SUSPENSION
            </h4>
            <p className="font-14 text-dark mb-2">
              4CEPS may temporarily suspend or terminate a seller account where there is reasonable evidence of:
            </p>
            <ul className="list-unstyled d-flex flex-column gap-1 ps-3 mb-3">
              <li className="font-14 text-dark">• Fraud;</li>
              <li className="font-14 text-dark">• Misrepresentation;</li>
              <li className="font-14 text-dark">• Regulatory non-compliance;</li>
              <li className="font-14 text-dark">• Repeated order failures;</li>
              <li className="font-14 text-dark">• Customer complaints;</li>
              <li className="font-14 text-dark">• Counterfeit or unsafe products;</li>
              <li className="font-14 text-dark">• Unauthorised activity; or</li>
              <li className="font-14 text-dark">• Violation of 4CEPS policies or applicable law.</li>
            </ul>
            <p className="font-14 text-dark mb-0">
              Where appropriate, sellers may be given an opportunity to provide clarification or corrective information.
            </p>
          </div>

          {/* 14. CUSTOMER COMMUNICATION */}
          <div className="mb-4 pb-3 border-bottom">
            <h4 className="fw-800 mb-3" style={{ color: "#A847F0", fontSize: "18px" }}>
              14. CUSTOMER COMMUNICATION
            </h4>
            <ul className="list-unstyled d-flex flex-column gap-2 ps-3 mb-0">
              <li className="font-14 text-dark">
                • Sellers should communicate with customers professionally and provide accurate information regarding orders, services, availability and applicable charges.
              </li>
              <li className="font-14 text-dark">
                • Sellers must not request sensitive payment credentials such as UPI PINs, CVVs, passwords or OTPs from customers.
              </li>
            </ul>
          </div>

          {/* 15. POLICY CHANGES */}
          <div className="mb-4 pb-3 border-bottom">
            <h4 className="fw-800 mb-3" style={{ color: "#A847F0", fontSize: "18px" }}>
              15. POLICY CHANGES
            </h4>
            <p className="font-14 text-dark mb-2">
              4CEPS may update this Seller Procedure from time to time to reflect changes in its services, operational processes or applicable laws.
            </p>
            <p className="font-14 text-dark mb-0">
              The updated procedure will be published on{" "}
              <a href="https://www.4ceps.com" target="_blank" rel="noopener noreferrer" className="text-primary text-decoration-underline">
                www.4ceps.com
              </a>
              .
            </p>
          </div>

          {/* 16. CONTACT */}
          <div>
            <h4 className="fw-800 mb-3" style={{ color: "#A847F0", fontSize: "18px" }}>
              16. CONTACT
            </h4>
            <div className="p-4 rounded-3 bg-light border" style={{ padding: "24px" }}>
              <p className="font-14 text-dark mb-1"><strong>RKTLC Innovations Pvt. Ltd.</strong></p>
              <p className="font-14 text-dark mb-1">Platform: <strong>4CEPS</strong></p>
              <p className="font-14 text-dark mb-1">
                Website:{" "}
                <a href="https://www.4ceps.com" target="_blank" rel="noopener noreferrer" className="text-primary text-decoration-underline">
                  www.4ceps.com
                </a>
              </p>
              <p className="font-14 text-dark mb-1">
                Email:{" "}
                <a href="mailto:contact@4ceps.com" className="text-primary text-decoration-underline">
                  contact@4ceps.com
                </a>
              </p>
              <p className="font-14 text-dark mb-1">Phone: <strong>7975854144</strong></p>
              <p className="font-14 text-dark mb-2">
                Registered Office: 151, Near Country Club, Sathanur Village, Bagalur Post, Bangalore North, Bangalore, Karnataka - 562149
              </p>
              <p className="font-12 text-muted mb-0">Last Updated: 18 August 2026</p>
            </div>
          </div>
        </div>
      </div>
    </>
  );
};

export default UserGuide;
